/* ── Drop caret and gap cursor ────────────────────────────
   Where a dragged selection will land, and where the caret sits between two
   block nodes. Both extensions ship enabled via StarterKit but neither draws
   anything useful on its own: prosemirror-gapcursor has no styles at all
   without its stylesheet, and the drop caret defaults to a 1px hairline in the
   body text colour. Vermilion matches the editorial marks elsewhere in the
   manuscript, so the insertion point reads as an instruction rather than
   as part of the prose. */
.twyne-editor .twyne-dropcursor {
  background-color: var(--color-vermilion);
  border-radius: 1px;
  box-shadow: 0 0 0 1px
    color-mix(in srgb, var(--color-vermilion) 25%, transparent);
}

.twyne-editor .ProseMirror-gapcursor {
  display: none;
  pointer-events: none;
  position: absolute;
}

.twyne-editor .ProseMirror-gapcursor::after {
  content: "";
  display: block;
  position: absolute;
  top: -2px;
  width: 1.25rem;
  border-top: 2px solid var(--color-vermilion);
  animation: twyne-gapcursor-blink 1.1s steps(2, start) infinite;
}

@keyframes twyne-gapcursor-blink {
  to {
    visibility: hidden;
  }
}

@media (prefers-reduced-motion: reduce) {
  .twyne-editor .ProseMirror-gapcursor::after {
    animation: none;
  }
}

.twyne-editor .ProseMirror-focused .ProseMirror-gapcursor,
.twyne-editor .ProseMirror-gapcursor:focus {
  display: block;
}

/* Page ornaments stay outside contentEditable. Nine-slice frames retain their
 * corners when a continuous manuscript grows or the sheet changes orientation. */
.page-canvas {
  container: manuscript-page / inline-size;
}
